18→    queryKey: ["platform_config"],
19→    queryFn: async (): Promise<PlatformConfig> => {
20→      const { data, error } = await supabase
21→        .from("platform_config")
22→        .select("max_resumes_per_job, max_file_size_mb, resume_retention_days")
23→        .limit(1)
