11→export async function logAuditAction(
12→  action: AuditAction,
13→  entityType: string,
14→  entityId?: string,
15→  details?: Record<string, any>,
16→) {
17→  try {
18→    const { data: { session } } = await supabase.auth.getSession();
19→    if (!session?.user?.id) return;
20→
21→    await (supabase as any).from("admin_audit_logs").insert({
22→      admin_user_id: session.user.id,
23→      action,
24→      entity_type: entityType,
25→      entity_id: entityId ?? null,
26→      details: details ?? {},
27→    });
28→  } catch {
29→    // Audit logging should never break the UI
30→  }
31→}
