 1→export function exportToCSV(data: Record<string, any>[], filename: string) {
 2→  if (!data.length) return;
 3→  const headers = Object.keys(data[0]);
 4→  const csvRows = [
 5→    headers.join(","),
 6→    ...data.map((row) =>
 7→      headers
 8→        .map((h) => {
 9→          const val = row[h] ?? "";
10→          const str = String(val).replace(/"/g, '""');
11→          return `"${str}"`;
12→        })
13→        .join(",")
14→    ),
15→  ];
16→  const blob = new Blob([csvRows.join("\n")], { type: "text/csv" });
17→  const url = URL.createObjectURL(blob);
18→  const a = document.createElement("a");
19→  a.href = url;
20→  a.download = `${filename}-${new Date().toISOString().slice(0, 10)}.csv`;
21→  a.click();
22→  URL.revokeObjectURL(url);
23→}
