 38→    } finally {
 39→      setLoading(false);
 40→    }
 41→  };
 42→
 43→  const handleSignIn = async (e: React.FormEvent) => {
 44→    e.preventDefault();
 45→    setLoading(true);
 46→    try {
 47→      const { error } = await supabase.auth.signInWithPassword({ email, password });
 48→      if (error) {
 49→        toast.error(error.message);
 50→      } else {
 51→        onSuccess?.();
