  1→import { useEffect } from "react";
  2→import { useLocation } from "react-router-dom";
  3→import { useSeoSettings, useSeoPages } from "@/hooks/useSeoSettings";
  4→
  5→/**
  6→ * Dynamic SEO head manager.
  7→ * Updates document meta tags based on admin-configured SEO settings.
  8→ * Supports per-page overrides that fall back to global settings.
  9→ */
 10→const SeoHead = () => {
 11→  const location = useLocation();
 12→  const { settings } = useSeoSettings();
 13→  const { pages } = useSeoPages();
 14→
 15→  useEffect(() => {
 16→    if (!settings) return;
 17→
 18→    const currentPage = pages.find((p) => p.page_path === location.pathname && p.is_active);
 19→
 20→    // Resolve with per-page overrides falling back to global
 21→    const title = currentPage?.title || settings.site_title || "Instant Resume Ranker";
 22→    const description = currentPage?.description || settings.site_description || "";
 23→    const keywords = currentPage?.keywords || settings.site_keywords || "";
 24→    const robots = currentPage?.meta_robots || settings.meta_robots || "index, follow";
 25→    const canonical = currentPage?.canonical_url || settings.canonical_url
 26→      ? `${(currentPage?.canonical_url || settings.canonical_url).replace(/\/$/, "")}${location.pathname}`
 27→      : "";
 28→    const ogTitle = currentPage?.og_title || settings.og_title || title;
 29→    const ogDescription = currentPage?.og_description || settings.og_description || description;
 30→    const ogImage = currentPage?.og_image_url || settings.og_image_url || "";
 31→    const ogType = settings.og_type || "website";
 32→    const ogSiteName = settings.og_site_name || settings.site_title || "";
 33→    const twitterCard = settings.twitter_card || "summary_large_image";
 34→    const twitterSite = settings.twitter_site || "";
 35→    const twitterCreator = settings.twitter_creator || "";
 36→    const twitterImage = settings.twitter_image_url || ogImage;
 37→
 38→    // Update document title
 39→    document.title = title;
 40→
 41→    // Helper to set/remove a meta tag
 42→    const setMeta = (attr: string, key: string, content: string) => {
 43→      if (!content) {
 44→        const existing = document.querySelector(`meta[${attr}="${key}"]`);
 45→        if (existing) existing.remove();
 46→        return;
 47→      }
 48→      let el = document.querySelector(`meta[${attr}="${key}"]`) as HTMLMetaElement;
 49→      if (!el) {
 50→        el = document.createElement("meta");
 51→        el.setAttribute(attr, key);
 52→        document.head.appendChild(el);
 53→      }
 54→      el.setAttribute("content", content);
 55→    };
 56→
 57→    // Standard meta
 58→    setMeta("name", "description", description);
 59→    setMeta("name", "keywords", keywords);
 60→    setMeta("name", "robots", robots);
 61→    setMeta("name", "theme-color", settings.theme_color || "");
 62→
 63→    // Bot-specific meta
 64→    if (settings.googlebot) setMeta("name", "googlebot", settings.googlebot);
 65→    if (settings.bingbot) setMeta("name", "bingbot", settings.bingbot);
 66→
 67→    // Verification meta
 68→    if (settings.google_search_console_id) setMeta("name", "google-site-verification", settings.google_search_console_id);
 69→    if (settings.bing_webmaster_id) setMeta("name", "msvalidate.01", settings.bing_webmaster_id);
 70→
 71→    // Open Graph
 72→    setMeta("property", "og:title", ogTitle);
 73→    setMeta("property", "og:description", ogDescription);
 74→    setMeta("property", "og:image", ogImage);
 75→    setMeta("property", "og:type", ogType);
 76→    setMeta("property", "og:site_name", ogSiteName);
 77→    if (canonical) setMeta("property", "og:url", canonical);
 78→    if (settings.facebook_app_id) setMeta("property", "fb:app_id", settings.facebook_app_id);
 79→
 80→    // Twitter Card
 81→    setMeta("name", "twitter:card", twitterCard);
 82→    setMeta("name", "twitter:title", ogTitle);
 83→    setMeta("name", "twitter:description", ogDescription);
 84→    setMeta("name", "twitter:image", twitterImage);
 85→    if (twitterSite) setMeta("name", "twitter:site", twitterSite);
 86→    if (twitterCreator) setMeta("name", "twitter:creator", twitterCreator);
 87→
 88→    // Canonical link
 89→    let linkCanonical = document.querySelector('link[rel="canonical"]') as HTMLLinkElement;
 90→    if (canonical) {
 91→      if (!linkCanonical) {
 92→        linkCanonical = document.createElement("link");
 93→        linkCanonical.setAttribute("rel", "canonical");
 94→        document.head.appendChild(linkCanonical);
 95→      }
 96→      linkCanonical.setAttribute("href", canonical);
 97→    } else if (linkCanonical) {
 98→      linkCanonical.remove();
 99→    }
100→
101→    // Structured Data (JSON-LD)
102→    const existingLd = document.getElementById("seo-jsonld");
103→    if (settings.structured_data_enabled) {
104→      const schemas: Record<string, any>[] = [];
105→
106→      // Organization schema
107→      const org: Record<string, any> = {
108→        "@context": "https://schema.org",
109→        "@type": "Organization",
110→        name: settings.organization_name || settings.site_title || "Instant Resume Ranker",
111→        description: settings.organization_description || description,
112→      };
113→      if (settings.organization_url) org.url = settings.organization_url;
114→      if (settings.organization_logo_url) org.logo = settings.organization_logo_url;
115→      schemas.push(org);
116→
117→      // WebApplication schema
118→      const webapp: Record<string, any> = {
119→        "@context": "https://schema.org",
120→        "@type": "WebApplication",
121→        name: settings.site_title || "Instant Resume Ranker",
122→        description: description,
123→        applicationCategory: "BusinessApplication",
124→        operatingSystem: "Web",
125→      };
126→      if (settings.organization_url) webapp.url = settings.organization_url;
127→      schemas.push(webapp);
128→
129→      // Per-page structured data
130→      if (currentPage?.structured_data_json && Object.keys(currentPage.structured_data_json).length > 0) {
131→        schemas.push(currentPage.structured_data_json);
132→      }
133→
134→      const script = existingLd || document.createElement("script");
135→      script.setAttribute("type", "application/ld+json");
136→      script.id = "seo-jsonld";
137→      script.textContent = JSON.stringify(schemas);
138→      if (!existingLd) document.head.appendChild(script);
139→    } else if (existingLd) {
140→      existingLd.remove();
141→    }
142→
143→    // Google Analytics
144→    if (settings.google_analytics_id && !document.getElementById("ga-script")) {
145→      const gaScript = document.createElement("script");
146→      gaScript.id = "ga-script";
147→      gaScript.async = true;
148→      gaScript.src = `https://www.googletagmanager.com/gtag/js?id=${settings.google_analytics_id}`;
149→      document.head.appendChild(gaScript);
150→
151→      const gaInit = document.createElement("script");
152→      gaInit.id = "ga-init";
153→      gaInit.textContent = `window.dataLayer=window.dataLayer||[];function gtag(){dataLayer.push(arguments);}gtag('js',new Date());gtag('config','${settings.google_analytics_id}');`;
154→      document.head.appendChild(gaInit);
155→    }
156→  }, [settings, pages, location.pathname]);
157→
158→  return null;
159→};
160→
161→export default SeoHead;
